/* bubble-sort both cards' listings (and their keys) by save time, oldest first */
static inline void sort_listings(void) {
    McFile *files;
    McFileKey *keys;
    s32 card;
    McFile swap;
    McFileKey swap_key;
    s32 i;
    s32 j;
    s32 count;

    for (card = 0; card < 2; card++) {
        files = fzgx_obj_lbl_1_bss_77380[card];
        keys = fzgx_obj_lbl_1_bss_7A39C[card];

        count = 0;
        for (i = 0; i < 127; i++) {
            if (files[i].size != 0) {
                count++;
            }
        }
        for (i = 0; i < count - 1; i++) {
            for (j = i + 1; j < count; j++) {
                if (files[i].time > files[j].time) {
                    swap = files[i];
                    files[i] = files[j];
                    files[j] = swap;
                    swap_key = keys[i];
                    keys[i] = keys[j];
                    keys[j] = swap_key;
                }
            }
        }
    }
}

